/* @autogenerated */
package net.civeira.phylax.integrationtest.feature.oauth.flow;

import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;

import io.quarkus.test.junit.QuarkusTest;
import io.restassured.RestAssured;
import io.restassured.http.ContentType;
import io.restassured.response.Response;
import io.restassured.specification.RequestSpecification;
import net.civeira.phylax.feature.oauth.tokensecurity.domain.TokenIntrospectionResult;
import net.civeira.phylax.integrationtest.feature.oauth.fixtures.OidcTestFixtures;

/**
 * Token exchange (RFC 8693, task 3.8): a client exchanges a token issued for it into one for a
 * registered audience, acting for the user ({@code act}); a wider scope, a foreign audience, a
 * token for another client, an actor token or an unregistered grant are refused.
 */
@QuarkusTest
class TokenExchangeFlowTest extends OidcIntegrationTestBase {

  private static final String TOKEN = "/oauth/openid/" + OidcTestFixtures.TENANT + "/token";
  private static final String GRANT = "urn:ietf:params:oauth:grant-type:token-exchange";
  private static final String ACCESS = "urn:ietf:params:oauth:token-type:access_token";

  private static RequestSpecification as(String clientId) {
    return RestAssured.given().auth().preemptive().basic(clientId, OidcTestFixtures.CLIENT_SECRET)
        .contentType(ContentType.URLENC);
  }

  private String userToken() {
    Response issued = as(OidcTestFixtures.CLIENT_ID).formParam("grant_type", "password")
        .formParam("username", OidcTestFixtures.USERNAME)
        .formParam("password", OidcTestFixtures.PASSWORD).formParam("scope", "openid profile")
        .post(TOKEN);
    Assertions.assertEquals(200, issued.statusCode(), issued.getBody().asString());
    return active(issued.jsonPath().getString("access_token"));
  }

  private String active(String token) {
    String jti = String.valueOf(decodeToken(token).get("jti"));
    tokenLookupGateway.storeByJti(jti,
        TokenIntrospectionResult.builder().active(true)
            .clientId(String.valueOf(decodeToken(token).get("client_id"))).jti(jti)
            .localSubject(OidcTestFixtures.USERNAME).build());
    return token;
  }

  private static Response exchange(String clientId, String subject, Map<String, String> extra) {
    return as(clientId).formParam("grant_type", GRANT).formParam("subject_token", subject)
        .formParam("subject_token_type", ACCESS).formParams(extra).post(TOKEN);
  }

  @Test
  void exchange_actsForTheUser_towardsARegisteredAudience() {
    Response exchanged = exchange(OidcTestFixtures.CLIENT_ID, userToken(),
        Map.of("audience", OidcTestFixtures.API_AUDIENCE, "scope", "profile"));

    Assertions.assertEquals(200, exchanged.statusCode(), exchanged.getBody().asString());
    Assertions.assertEquals(ACCESS, exchanged.jsonPath().getString("issued_token_type"));
    Assertions.assertNull(exchanged.jsonPath().getString("refresh_token"));
    Map<String, Object> claims = decodeToken(exchanged.jsonPath().getString("access_token"));
    Assertions.assertEquals(OidcTestFixtures.USERNAME, claims.get("sub"));
    Assertions.assertEquals(OidcTestFixtures.CLIENT_ID, ((Map<?, ?>) claims.get("act")).get("sub"));
    Assertions.assertTrue(claimAsList(claims.get("aud")).contains(OidcTestFixtures.API_AUDIENCE));
    Assertions.assertEquals(List.of("profile"), claimAsList(claims.get("scope")));
  }

  @Test
  void exchangeOfAnExchangedToken_nestsTheActor() {
    String first = active(exchange(OidcTestFixtures.CLIENT_ID, userToken(), Map.of()).jsonPath()
        .getString("access_token"));
    Response second = exchange(OidcTestFixtures.CLIENT_ID, first, Map.of());
    Assertions.assertEquals(200, second.statusCode(), second.getBody().asString());
    Map<?, ?> act = (Map<?, ?>) decodeToken(second.jsonPath().getString("access_token")).get("act");
    Assertions.assertNotNull(act.get("act"));
  }

  @Test
  void widerScope_isInvalidScope() {
    Response response = exchange(OidcTestFixtures.CLIENT_ID, userToken(), Map.of("scope", "email"));
    Assertions.assertEquals(400, response.statusCode());
    Assertions.assertEquals("invalid_scope", response.jsonPath().getString("error"));
  }

  @Test
  void foreignAudience_isInvalidTarget() {
    Response response =
        exchange(OidcTestFixtures.CLIENT_ID, userToken(), Map.of("audience", "foreign-api"));
    Assertions.assertEquals(400, response.statusCode());
    Assertions.assertEquals("invalid_target", response.jsonPath().getString("error"));
  }

  @Test
  void tokenIssuedForAnotherClient_isInvalidGrant() {
    Response response = exchange(OidcTestFixtures.WEB_CLIENT_ID, userToken(), Map.of());
    Assertions.assertEquals(400, response.statusCode());
    Assertions.assertEquals("invalid_grant", response.jsonPath().getString("error"));
  }

  @Test
  void actorToken_andOtherTokenTypes_areInvalidRequests() {
    String subject = userToken();
    Assertions.assertEquals("invalid_request",
        exchange(OidcTestFixtures.CLIENT_ID, subject,
            Map.of("actor_token", subject, "actor_token_type", ACCESS)).jsonPath()
                .getString("error"));
    Assertions.assertEquals("invalid_request",
        exchange(OidcTestFixtures.CLIENT_ID, subject,
            Map.of("requested_token_type", "urn:ietf:params:oauth:token-type:refresh_token"))
                .jsonPath().getString("error"));
  }

  @Test
  void clientWithoutTheGrant_isUnauthorized() {
    String subject = userToken();
    clientStoreGateway.setAllowedGrants(List.of("password"));
    Response response = exchange(OidcTestFixtures.CLIENT_ID, subject, Map.of());
    Assertions.assertEquals("unauthorized_client", response.jsonPath().getString("error"));
  }
}
